// The schema this repository declares, read out of the SQL that creates it.
//
// One parser, two users: the generator writes the manifest, the test re-reads it and fails when the
// two disagree. That is what keeps a generated file from going stale in a way nobody notices.
//
// KNOWN LIMIT: the manifest can only say what a column IS, never that one was removed. A migration
// with DROP COLUMN or RENAME COLUMN leaves the old name declared and the drift check then raises a
// critical incident, on every boot, about the column the migration deliberately took away. Whoever
// writes the first such migration must edit the base-schema block in the same commit so the parser
// stops seeing it — and the live-database comparison in tests/integration/db-roundtrip.test.ts is
// what will say so.
//
// It reads the WHOLE file rather than only the base-schema block, because migrations create tables
// too (asset_collections, chat_viewer_requests and three others) and migrations run on a fresh
// install as well. What a fresh install ends up with is the union, and the union is what an old
// install has to match.
import { readFileSync } from "node:fs";

/**
 * Lines inside a CREATE TABLE body that name a constraint rather than a column.
 *
 * The closing paren is matched with an OPTIONAL semicolon: schema_migrations ends its statement on
 * the next line instead, and requiring the semicolon made the body run on through the surrounding
 * JavaScript, which contributed "async", "await", "const", "for", "if", "new", "return" and "try"
 * as columns. The live database caught that, which is the point of comparing against one.
 */
const CONSTRAINT = /^(PRIMARY|UNIQUE|FOREIGN|CONSTRAINT|CHECK)\b/i;

export function parseDeclaredSchema(sourcePath) {
  const source = readFileSync(sourcePath, "utf8");
  const tables = new Map();
  const add = (table, column) => {
    if (!tables.has(table)) tables.set(table, new Set());
    tables.get(table).add(column);
  };

  for (const match of source.matchAll(/CREATE TABLE IF NOT EXISTS (\w+)\s*\(([\s\S]*?)\n\s*\)\s*;?/g)) {
    for (const raw of match[2].split("\n")) {
      const line = raw.trim();
      if (!line || line.startsWith("--") || CONSTRAINT.test(line)) continue;
      const column = line.match(/^(\w+)\s+\S/);
      if (column) add(match[1], column[1]);
    }
  }
  for (const match of source.matchAll(/ALTER TABLE (\w+) ADD COLUMN IF NOT EXISTS (\w+)/g)) {
    add(match[1], match[2]);
  }

  return Object.fromEntries(
    [...tables]
      .map(([table, columns]) => [table, [...columns].sort()])
      .sort((a, b) => a[0].localeCompare(b[0]))
  );
}

export function renderManifest(schema) {
  const body = Object.entries(schema)
    .map(([table, columns]) => `  ${table}: [${columns.map((c) => `"${c}"`).join(", ")}]`)
    .join(",\n");
  return `// GENERATED by scripts/generate-schema-manifest.mjs. Do not edit by hand.
//
// The columns a database is supposed to have once the base schema and every migration have run.
// Checked against the live database at startup, because a column that exists only in the source is
// a write that fails on an install nobody rebuilt: the base-schema block is itself a migration
// under one fixed id, so adding a column there alone reaches a fresh install and nothing else.
export const DECLARED_SCHEMA: Record<string, string[]> = {
${body}
};
`;
}
